// Contract helper: feed real API responses (generated by pytest with TestClient) through the
// page helpers and print what the page would derive from them, as one JSON object.
// Usage: node tests/js/home_contract.mjs <home.js> <input.json>
// input.json: {"demo_infos": {name: demoInfo}, "bug_responses": {name: bugCheckResponse}}
// No DOM and no network: only pure helpers are called.

import { readFile } from "node:fs/promises";
import { pathToFileURL } from "node:url";

const [homePath, inputPath] = process.argv.slice(2);
if (!homePath || !inputPath) {
  process.stderr.write("usage: home_contract.mjs <home.js> <input.json>\n");
  process.exit(2);
}

const home = await import(pathToFileURL(homePath).href);
const voice = await import(new URL("./voice.js", pathToFileURL(homePath)).href);
const input = JSON.parse(await readFile(inputPath, "utf8"));

const out = { demo_infos: {}, bug_responses: {} };
for (const [name, info] of Object.entries(input.demo_infos ?? {})) {
  out.demo_infos[name] = {
    actions: home.limitText("Issue filing", info.actions),
    voice: home.limitText("Voice calls", info.voice),
    sandbox: home.sandboxLink(info),
    links: home.projectLinks(info.source_repo_url),
  };
}
for (const [name, data] of Object.entries(input.bug_responses ?? {})) {
  out.bug_responses[name] = {
    can_file_anyway: voice.canFileAnyway(data),
    proposal_ready: voice.isProposalReady(data.proposed_action),
    agent_result: JSON.parse(voice.toAgentBugResult(data)),
  };
}
out.file_anyway_body = voice.buildFileAnywayBody(input.last_check_body ?? null);
process.stdout.write(JSON.stringify(out));
